mapper.select:
/* RiskImpr01Mapper.countUserSiteAuth */
SELECT
    COUNT(1)
FROM TB_USER_SITE_AUTH A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.USER_CD = #{userCd}
  AND A.SITE_CD = #{siteCd}
  AND A.USE_YN = 'Y'

/* RiskImpr01Mapper.selectAssessmentStatus */
SELECT
    A.ASSESSMENT_STATUS
FROM TB_RISK_ASSESSMENT A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.PROCESS_CD = #{processCd}
  AND A.ASSESSMENT_CD = #{assessmentCd}

/* RiskImpr01Mapper.selectNextImprovementSeq */
SELECT
    IFNULL(MAX(A.IMPROVEMENT_SEQ), 0) + 1
FROM TB_RISK_IMPROVEMENT_ITEM A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.PROCESS_CD = #{processCd}
  AND A.ASSESSMENT_CD = #{assessmentCd}

/* RiskImpr01Mapper.countActiveImprovementItems */
SELECT
    COUNT(1)
FROM TB_RISK_IMPROVEMENT_ITEM A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.PROCESS_CD = #{processCd}
  AND A.ASSESSMENT_CD = #{assessmentCd}
  AND A.USE_YN = 'Y'

mapper.insert:
/* RiskImpr01Mapper.insertImprovementItem */
INSERT INTO TB_RISK_IMPROVEMENT_ITEM
(
    CMPNY_CD
  , SITE_CD
  , PROCESS_CD
  , ASSESSMENT_CD
  , IMPROVEMENT_SEQ
  , IMPROVE_DATE
  , IMPROVE_DESC
  , FILE_MGMT_CD
  , LIKELIHOOD_SCORE
  , SEVERITY_SCORE
  , RISK_LV
  , USE_YN
  , INSERT_NO
  , INSERT_DATE
)
VALUES
(
    #{gvCmpnyCd}
  , #{siteCd}
  , #{processCd}
  , #{assessmentCd}
  , #{improvementSeq}
  , #{improveDate}
  , #{improveDesc}
  , #{fileMgmtCd}
  , #{likelihoodScore}
  , #{severityScore}
  , #{riskLv}
  , 'Y'
  , #{gvUserCd}
  , NOW()
)

mapper.update:
/* RiskImpr01Mapper.updateImprovementItem */
UPDATE TB_RISK_IMPROVEMENT_ITEM
SET
    IMPROVE_DATE     = #{improveDate}
  , IMPROVE_DESC     = #{improveDesc}

  , FILE_MGMT_CD     = #{fileMgmtCd}

  , LIKELIHOOD_SCORE = #{likelihoodScore}
  , SEVERITY_SCORE   = #{severityScore}
  , RISK_LV          = #{riskLv}
  , UPDATE_NO        = #{gvUserCd}
  , UPDATE_DATE      = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND PROCESS_CD = #{processCd}
  AND ASSESSMENT_CD = #{assessmentCd}
  AND IMPROVEMENT_SEQ = #{improvementSeq}
  AND USE_YN = 'Y'

/* RiskImpr01Mapper.softDeleteImprovementItem */
UPDATE TB_RISK_IMPROVEMENT_ITEM
SET
    USE_YN      = 'N'
  , UPDATE_NO   = #{userCd}
  , UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{cmpnyCd}
  AND SITE_CD = #{siteCd}
  AND PROCESS_CD = #{processCd}
  AND ASSESSMENT_CD = #{assessmentCd}
  AND IMPROVEMENT_SEQ = #{improvementSeq}
  AND USE_YN = 'Y'

/* RiskImpr01Mapper.updateAssessmentComplete */
UPDATE TB_RISK_ASSESSMENT
SET
    ASSESSMENT_STATUS      = '003'
  , REVAL_LIKELIHOOD_SCORE = #{revalLikelihoodScore}
  , REVAL_SEVERITY_SCORE   = #{revalSeverityScore}
  , REVAL_RISK_LV          = #{revalRiskLv}

  , REVAL_DESC             = #{revalDesc}


  , REVAL_DATE             = #{revalDate}

  , REVAL_ASSESSOR_ID      = #{gvUserCd}
  , REVAL_ASSESS_DATE      = NOW()
  , UPDATE_NO              = #{gvUserCd}
  , UPDATE_DATE            = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND PROCESS_CD = #{processCd}
  AND ASSESSMENT_CD = #{assessmentCd}
  AND ASSESSMENT_STATUS = '005'
